#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;math.h&gt;

/* Evaluates P(x) and P'(x) in a single pass using Horner's method */
void horner_eval(const double *coeffs, int degree, double x, double *p_val, double *dp_val) {
    double p = coeffs[degree];
    double dp = 0.0;

    for (int i = degree - 1; i &gt;= 0; i--) {
        dp = dp * x + p;
        p = p * x + coeffs[i];
    }
    *p_val = p;
    *dp_val = dp;
}

/* Performs synthetic deflation: divides P(x) by (x - root) */
void deflate(double *coeffs, int *degree, double root) {
    int n = *degree;
    double *q = (double *)malloc(n * sizeof(double));
    q[n - 1] = coeffs[n];
    for (int i = n - 2; i &gt;= 0; i--) {
        q[i] = coeffs[i + 1] + root * q[i + 1];
    }
    for (int i = 0; i &lt; n; i++) {
        coeffs[i] = q[i];
    }
    free(q);
    (*degree)--;
}

/* Finds a single real root using Newton-Raphson */
int find_root_newton(const double *coeffs, int degree, double x0, double tol, int max_iter, double *root) {
    double x = x0;
    for (int iter = 0; iter &lt; max_iter; iter++) {
        double p, dp;
        horner_eval(coeffs, degree, x, &p, &dp);
        if (fabs(p) &lt; tol) {
            *root = x;
            return 1;
        }
        if (fabs(dp) &lt; 1e-14) break;
        x -= p / dp;
    }
    *root = x;
    return 0;
}

int main(void) {
    /* P(x) = x^3 - 6x^2 + 11x - 6 = (x-1)(x-2)(x-3) */
    /* coeffs ordered as [a0, a1, a2, a3] */
    double coeffs[4] = {-6.0, 11.0, -6.0, 1.0};
    int degree = 3;
    double root;

    printf("=== C99 Horner & Newton Root Finder ===\n");
    while (degree &gt; 0) {
        if (find_root_newton(coeffs, degree, 0.5, 1e-12, 100, &root)) {
            printf("Found Root: %12.8f\n", root);
            deflate(coeffs, &degree, root);
        } else {
            printf("Convergence failed or complex root encountered.\n");
            break;
        }
    }
    return 0;
}


#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;cmath&gt;
#include &lt;numeric&gt;
#include &lt;iomanip&gt;

class Polynomial {
public:
    // Coefficients ordered from lowest degree to highest: a0, a1, ..., an
    std::vector&lt;double&gt; coeffs;

    Polynomial(std::initializer_list&lt;double&gt; c) : coeffs(c) {}
    Polynomial(std::vector&lt;double&gt; c) : coeffs(std::move(c)) {}

    int degree() const { return static_cast&lt;int&gt;(coeffs.size()) - 1; }

    // Evaluates P(x) and P'(x) simultaneously via Horner's Rule
    std::pair&lt;double, double&gt; eval_with_derivative(double x) const {
        int n = degree();
        double p = coeffs[n];
        double dp = 0.0;
        for (int i = n - 1; i &gt;= 0; --i) {
            dp = dp * x + p;
            p = p * x + coeffs[i];
        }
        return {p, dp};
    }

    // Synthetic Deflation: returns quotient polynomial when divided by (x - root)
    Polynomial deflated(double root) const {
        int n = degree();
        std::vector&lt;double&gt; q(n);
        q[n - 1] = coeffs[n];
        for (int i = n - 2; i &gt;= 0; --i) {
            q[i] = coeffs[i + 1] + root * q[i + 1];
        }
        return Polynomial(q);
    }

    // Finds a real root via Newton-Raphson iteration
    bool solve_newton(double x0, double& root, double tol = 1e-12, int max_iter = 100) const {
        double x = x0;
        for (int iter = 0; iter &lt; max_iter; ++iter) {
            auto [p, dp] = eval_with_derivative(x);
            if (std::abs(p) &lt; tol) {
                root = x;
                return true;
            }
            if (std::abs(dp) &lt; 1e-15) return false;
            x -= p / dp;
        }
        root = x;
        return false;
    }
};

int main() {
    // P(x) = (x-1)(x-2)(x-3) = x^3 - 6x^2 + 11x - 6
    Polynomial poly{-6.0, 11.0, -6.0, 1.0};

    std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(8);
    std::cout &lt;&lt; "=== C++17 Polynomial Solver ===\n";

    while (poly.degree() &gt; 0) {
        double root = 0.0;
        if (poly.solve_newton(0.5, root)) {
            std::cout &lt;&lt; "Extracted Root: " &lt;&lt; root &lt;&lt; "\n";
            poly = poly.deflated(root);
        } else {
            std::cout &lt;&lt; "No further real roots found.\n";
            break;
        }
    }
    return 0;
}


#!/usr/bin/env python3
"""
Production polynomial evaluation and root-finding using Horner's rule,
Newton-Raphson with synthetic deflation, and the Companion Matrix.
"""
from typing import Tuple, List
import numpy as np

def horner_eval(coeffs: List[float], x: float) -&gt; Tuple[float, float]:
    """
    Evaluates P(x) and P'(x) in a single pass using Horner's scheme.
    coeffs is ordered [a0, a1, ..., an].
    """
    n = len(coeffs) - 1
    p = coeffs[n]
    dp = 0.0
    for i in range(n - 1, -1, -1):
        dp = dp * x + p
        p = p * x + coeffs[i]
    return p, dp

def synthetic_deflation(coeffs: List[float], root: float) -&gt; List[float]:
    """Divides P(x) by (x - root) via synthetic division."""
    n = len(coeffs) - 1
    q = [0.0] * n
    q[n - 1] = coeffs[n]
    for i in range(n - 2, -1, -1):
        q[i] = coeffs[i + 1] + root * q[i + 1]
    return q

def find_root_newton(coeffs: List[float], x0: float = 0.5, tol: float = 1e-12, max_iter: int = 100) -&gt; float:
    """Finds a root using Newton-Raphson iteration."""
    x = x0
    for _ in range(max_iter):
        p, dp = horner_eval(coeffs, x)
        if abs(p) &lt; tol:
            return x
        if abs(dp) &lt; 1e-15:
            raise ArithmeticError("Derivative vanished during iteration.")
        x -= p / dp
    return x

if __name__ == "__main__":
    # P(x) = (x - 1)(x - 2)(x - 3) = x^3 - 6x^2 + 11x - 6
    coeffs = [-6.0, 11.0, -6.0, 1.0]
    print("=== Python Horner & Companion Matrix Solver ===")

    current_coeffs = list(coeffs)
    roots = []
    for _ in range(len(coeffs) - 1):
        r = find_root_newton(current_coeffs, x0=0.0)
        roots.append(r)
        current_coeffs = synthetic_deflation(current_coeffs, r)

    print(f"Roots via Horner + Newton: {roots}")

    # Validation via NumPy Frobenius Companion Matrix
    # np.roots expects coefficients in descending order [an, ..., a0]
    np_roots = np.roots(coeffs[::-1])
    print(f"Roots via Companion Matrix (QR): {np_roots}")


module polynomial_solver
    use, intrinsic :: iso_fortran_env, only: real64
    implicit none
    private
    public :: horner_eval, synthetic_deflate, newton_solve

contains

    subroutine horner_eval(coeffs, n, x, p, dp)
        real(real64), intent(in)  :: coeffs(0:n)
        integer,      intent(in)  :: n
        real(real64), intent(in)  :: x
        real(real64), intent(out) :: p, dp
        integer :: i

        p = coeffs(n)
        dp = 0.0_real64
        do i = n - 1, 0, -1
            dp = dp * x + p
            p = p * x + coeffs(i)
        end do
    end subroutine horner_eval

    subroutine synthetic_deflate(coeffs, n, root, q)
        real(real64), intent(in)  :: coeffs(0:n)
        integer,      intent(in)  :: n
        real(real64), intent(in)  :: root
        real(real64), intent(out) :: q(0:n-1)
        integer :: i

        q(n-1) = coeffs(n)
        do i = n - 2, 0, -1
            q(i) = coeffs(i+1) + root * q(i+1)
        end do
    end subroutine synthetic_deflate

    logical function newton_solve(coeffs, n, x0, tol, max_iter, root)
        real(real64), intent(in)  :: coeffs(0:n)
        integer,      intent(in)  :: n
        real(real64), intent(in)  :: x0, tol
        integer,      intent(in)  :: max_iter
        real(real64), intent(out) :: root
        real(real64) :: x, p, dp
        integer :: iter

        x = x0
        newton_solve = .false.
        do iter = 1, max_iter
            call horner_eval(coeffs, n, x, p, dp)
            if (abs(p) &lt; tol) then
                root = x
                newton_solve = .true.
                return
            end if
            if (abs(dp) &lt; 1.0e-14_real64) exit
            x = x - p / dp
        end do
        root = x
    end function newton_solve

end module polynomial_solver

program test_poly
    use, intrinsic :: iso_fortran_env, only: real64
    use polynomial_solver
    implicit none

    real(real64) :: coeffs(0:3) = [-6.0_real64, 11.0_real64, -6.0_real64, 1.0_real64]
    real(real64) :: q(0:2), q2(0:1), root
    logical :: success

    print *, "=== Fortran 2008 Modular Horner Solver ==="

    success = newton_solve(coeffs, 3, 0.5_real64, 1.0e-12_real64, 100, root)
    if (success) then
        print '(A, F12.8)', " Found Root 1: ", root
        call synthetic_deflate(coeffs, 3, root, q)
    end if

    success = newton_solve(q, 2, 1.5_real64, 1.0e-12_real64, 100, root)
    if (success) then
        print '(A, F12.8)', " Found Root 2: ", root
        call synthetic_deflate(q, 2, root, q2)
    end if

    success = newton_solve(q2, 1, 2.5_real64, 1.0e-12_real64, 100, root)
    if (success) then
        print '(A, F12.8)', " Found Root 3: ", root
    end if

end program test_poly
